package ai.decisionos.aside;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import org.json.*;import java.io.*;
/** Real device checks: no login, message send, review post, payment, or assignment submission. */
final class CampusHubChecks {
 static void run(GoalInstrumentation i){Bundle out=new Bundle();GoalAgentActivity a=null;String gid="",jobId="";int start=i.checks;try(GoalStore goals=new GoalStore(i.getTargetContext());CampusFlowStore store=new CampusFlowStore(i.getTargetContext())){
  i.check(CampusWorkflows.ALL.length==16,"all sixteen workflows available");java.util.Set<String> ids=new java.util.HashSet<>();for(CampusWorkflows.Flow f:CampusWorkflows.ALL){i.check(ids.add(f.id),"unique flow "+f.id);i.check(CampusWorkflows.get(f.id)==f,"lookup "+f.id);String request=CampusWorkflows.request(f,"TEST_CONTEXT");i.check(request.contains("TEST_CONTEXT")&&request.contains("발송·게시·구매·최종 제출 권한이 없어"),"draft-only execution contract "+f.id);}
  i.check(!CampusFlowStore.verifiedConnection("portal","https://portal.unist.ac.kr/",false,false),"open page not connected");i.check(!CampusFlowStore.verifiedConnection("portal","https://portal.unist.ac.kr.evil.invalid/",false,true),"suffix spoof blocked");i.check(!CampusFlowStore.verifiedConnection("portal","https://portal.unist.ac.kr/",true,true),"password login page blocked");i.check(CampusFlowStore.verifiedConnection("portal","https://portal.unist.ac.kr/",false,true),"same host login evidence accepted");i.check(!CampusFlowStore.verifiedConnection("portal","http://portal.unist.ac.kr/",false,true),"http rejected");
  String ics="BEGIN:VCALENDAR\nBEGIN:VEVENT\nUID:test-day\nSUMMARY:기말 시험\nDTSTART;VALUE=DATE:20261107\nDTEND;VALUE=DATE:20261108\nEND:VEVENT\nBEGIN:VEVENT\nUID:test-utc\nSUMMARY:과제 마감\nDTSTART:20261107T010000Z\nDTEND:20261107T020000Z\nEND:VEVENT\nEND:VCALENDAR";java.util.List<CampusCalendar.Event> events=CampusCalendar.parse(ics);i.check(events.size()==2&&events.get(0).all,"ICS all-day preserved");i.check(events.get(1).start.equals("2026-11-07T10:00")&&events.get(1).zone.equals("Asia/Seoul"),"UTC deadline converted exactly");boolean repeat=false;try{CampusCalendar.parse(ics.replace("UID:test-day","RRULE:FREQ=WEEKLY\nUID:test-day"));}catch(IllegalArgumentException e){repeat=true;}i.check(repeat,"unsupported recurrence not silently changed");boolean date=false;try{CampusCalendar.parse(ics.replace("20261107","20261399"));}catch(Exception e){date=true;}i.check(date,"invalid dates rejected");
  String body="한글 신청서 <항목> & 사실 확인\n둘째 줄";String doc=CompanionDocumentPreview.read(new ByteArrayInputStream(CampusDocx.bytes("시험 문서",body)));i.check(doc.contains("<항목> & 사실 확인")&&doc.contains("둘째 줄"),"DOCX XML escaping and Korean roundtrip");
  JSONObject fixture=new JSONObject();GoalStore.put(fixture,"flow","application");GoalStore.put(fixture,"title","REGRESSION_CAMPUS_HUB");GoalStore.put(fixture,"context","fixture");GoalStore.put(fixture,"state","draft");jobId=store.save("jobs",fixture);try(CampusFlowStore reopened=new CampusFlowStore(i.getTargetContext())){i.check(reopened.get(jobId).optString("context").equals("fixture"),"work queue persists");}i.check(CampusFlowStore.state(fixture).equals("요청 초안"),"draft not completed");GoalStore.put(fixture,"state","approved");i.check(CampusFlowStore.state(fixture).contains("서비스에서 실행 필요"),"approval not a send receipt");
  gid=goals.create("grades","REGRESSION_CAMPUS_HUB","학교",0).optString("id");a=(GoalAgentActivity)i.startActivitySync(new Intent(i.getTargetContext(),GoalAgentActivity.class).putExtra("goal_id",gid).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final GoalAgentActivity host=a;i.runOnMainSync(()->host.relay.stop());
  final android.webkit.WebView[] testWeb={null};final String[] extraction={null};java.util.concurrent.CountDownLatch loaded=new java.util.concurrent.CountDownLatch(1);i.runOnMainSync(()->{testWeb[0]=new android.webkit.WebView(host);testWeb[0].getSettings().setJavaScriptEnabled(true);testWeb[0].setWebViewClient(new android.webkit.WebViewClient(){public void onPageFinished(android.webkit.WebView v,String url){v.evaluateJavascript(CampusHubUi.PAGE_SCRIPT,value->{extraction[0]=value;loaded.countDown();});}});testWeb[0].loadDataWithBaseURL("https://example.invalid/","<html><title>TEST</title><body><p>기말 시험 안내</p><input value='SECRET_INPUT'><textarea>SECRET_TEXT</textarea><script>var secret='SECRET_SCRIPT'</script></body></html>","text/html","UTF-8",null);});i.check(loaded.await(10,java.util.concurrent.TimeUnit.SECONDS),"DOM extractor executes");i.check(extraction[0]!=null&&!extraction[0].equals("null"),"DOM extractor returns JSON");JSONObject extracted=new JSONObject(new JSONArray("["+extraction[0]+"]").getString(0));i.check(extracted.optString("text").contains("기말 시험 안내")&&!extracted.optString("text").contains("SECRET"),"DOM text excludes inputs, textarea, script");i.runOnMainSync(()->testWeb[0].destroy());
  for(String page:new String[]{"학교 시작하기","학교 알림","학교 자동화","학교 작업","AI 답변 비교"}){i.runOnMainSync(()->host.chat.companion.select(page));i.waitForIdleSync();i.check(host.chat.companion.page.equals(page),"route "+page);i.check(host.chat.companion.sideBody.getChildCount()>0,"content "+page);CompanionOnlyChecks.capture(i,"campus-"+page);}
  i.runOnMainSync(()->{host.chat.companion.select("학교 시작하기");String text=RedesignChecks.texts(host.chat.companion.sideBody);for(int n=0;n<5;n++)i.check(text.contains(CampusWorkflows.SERVICES[n][1]),"tutorial service "+CampusWorkflows.SERVICES[n][0]);host.chat.companion.select("학교 자동화");String catalog=RedesignChecks.texts(host.chat.companion.sideBody);for(CampusWorkflows.Flow f:CampusWorkflows.ALL)i.check(catalog.contains(f.title),"catalog entry "+f.id);host.chat.companion.select("AI 답변 비교");String compare=RedesignChecks.texts(host.chat.companion.sideBody);for(String name:new String[]{"누비","ChatGPT","Claude","Gemini"})i.check(compare.contains(name),"four result slots "+name);});
  String deleted=goals.create("grades","REGRESSION_CAMPUS_DELETED","学校",0).optString("id");String deletedConversation=goals.defaultConversation(deleted).optString("id");goals.deleteGoal(deleted);boolean missing=false;try{goals.saveConversation(deletedConversation,new JSONArray(),"orphan");}catch(IllegalArgumentException expected){missing=true;}i.check(missing,"deleted conversation save rejected without recreation");
  out.putString("stream","PASS "+(i.checks-start)+" campus tutorial, workflow, document and UI checks\n");
 }catch(Throwable t){out.putString("stream","FAIL "+t+"\n");}finally{if(a!=null){GoalAgentActivity host=a;i.runOnMainSync(host::finish);i.waitForIdleSync();}if(!gid.isEmpty())try(GoalStore s=new GoalStore(i.getTargetContext())){s.deleteGoal(gid);}if(!jobId.isEmpty())try(CampusFlowStore s=new CampusFlowStore(i.getTargetContext())){s.remove(jobId);}i.finish(out.getString("stream","").startsWith("PASS")?-1:0,out);}}
}
